import {marketMap,forestMap,BOARD,TRADER} from './life-access.js?v=54';
import {decorDescription} from './decor-spec.js?v=54';
import {LIFE_SHOPS,shopMap,atLifeShop,woodReady,collectWood,woodId} from './life-shops.js?v=54';
import {CROPS,DECOR,HOME_LEVELS,setLifeLevel,buyLife,buyLumber,upgradeHome,openPaddy} from './homestead.js?v=54';
import {canGrow,UPGRADE_GATES} from './life-progression.js?v=54';
export function createLifeShopUI(api){
 const {$,panel,imageTag,toast,save,hud,esc}=api,s=()=>api.state(),h=()=>s().ancient.home;
 const done=text=>{save();hud();toast(text);};
 const money=()=>`<p class="life-wallet">보유 ${s().coins.toLocaleString()}엽전 · 목재 ${s().inventory.lumber||0}개 · 가죽 ${s().inventory.hide||0}개 · 평판 ${h().reputation}/100</p>`;
 function guide(kind){const d=LIFE_SHOPS[kind];api.guideShop(kind);panel(d.name+' 안내',`<h3>생활마을 북쪽 길 건너 상점 거리</h3><p>${d.name}에서 필요한 물건을 마련할 수 있어.</p><p>가게 문 앞에서 조사해 들어간 뒤 상인에게 말을 걸어 보자.</p><p class="note">목재는 목공소에서 사거나 마을 남서쪽 길 건너 외곽 숲 두 곳에서 주울 수 있어.</p><button id="life-guide-close" class="primary full">가게 방향 기억하기</button>`);$('#life-guide-close').onclick=api.close;}
 function show(kind){if(!atLifeShop(s(),kind)){guide(kind);return;}const d=LIFE_SHOPS[kind];
  panel(d.name,`<div class="life-order-heading">${imageTag('shop-merchant-'+kind,d.merchant)}<div><h3>${d.merchant}</h3><p>${d.line}</p>${money()}</div></div><div id="life-store-body">${kind==='seed'?seeds():kind==='tool'?api.toolCards():kind==='wood'?wood():decor()}</div><p class="note">구입한 물건과 도구는 집과 마당에서 사용할 수 있어.</p>`,{wide:true,type:'life-shop'});
  if(kind==='tool')api.bindTools(()=>show(kind));
  document.querySelectorAll('[data-store-seed]').forEach(b=>b.onclick=()=>{if(buyLife(s(),'seed',b.dataset.storeSeed,Number(b.dataset.count)))done(CROPS[b.dataset.storeSeed].name+' 씨앗 '+b.dataset.count+'개를 샀다.');show(kind);});
  document.querySelectorAll('[data-store-lumber]').forEach(b=>b.onclick=()=>{if(buyLumber(s(),Number(b.dataset.storeLumber)))done('목재 '+b.dataset.storeLumber+'개를 샀다.');show(kind);});
  document.querySelectorAll('[data-store-decor]').forEach(b=>b.onclick=()=>{if(buyLife(s(),'decor',b.dataset.storeDecor))done(DECOR[b.dataset.storeDecor].name+' 구입 완료!');show(kind);});
  if($('#store-upgrade'))$('#store-upgrade').onclick=()=>{if(!atLifeShop(s(),'wood')||!canGrow(s()))return;const next=HOME_LEVELS[h().level+1];panel('거처 확장 의뢰',`<h3>${h().level+1}단계로 키울까?</h3><p>${next.coins}엽전 · 목재 ${next.lumber}개를 쓴다. 심은 작물과 살림은 그대로 남아.</p><button id="store-upgrade-confirm" class="primary full">집 키우기</button><button id="store-upgrade-back" class="full">나중에</button>`);$('#store-upgrade-confirm').onclick=()=>{if(upgradeHome(s())){api.refreshWorld();done('거처가 '+h().level+'단계로 자랐다!');}show('wood');};$('#store-upgrade-back').onclick=()=>show('wood');};
  if($('#store-paddy'))$('#store-paddy').onclick=()=>{if(openPaddy(s()))done('내 마당에 논 한 칸을 열었다.');show('wood');};
  if($('#store-cart'))$('#store-cart').onclick=api.cart;
 }
 function seeds(){return `<h3>밭·논 씨앗</h3><div class="life-shop-grid">${Object.entries(CROPS).map(([id,c])=>`<article>${imageTag('life-seed-'+id,c.name+' 씨앗')}<div><b>${c.name} 씨앗</b><p>${c.minutes}분 · 한 칸 수확 ${c.yield}개</p><small>개당 ${c.seed}엽전 · 보유 ${h().seeds[id]}개${c.kind==='paddy'?' · 논 전용':''}</small><div class="life-bundle-buttons">${[1,5,10].map(n=>`<button data-store-seed="${id}" data-count="${n}" ${s().coins<c.seed*n||h().seeds[id]+n>99999||(c.kind==='paddy'&&!h().paddies)?'disabled':''}>${n}개 · ${n*c.seed}엽전</button>`).join('')}</div>${c.kind==='paddy'&&!h().paddies?'<p class="note">거처 3단계에서 논을 먼저 열어 줘.</p>':''}</div></article>`).join('')}</div>`;}
 function wood(){const next=HOME_LEVELS[h().level+1],g=UPGRADE_GATES[h().level+1];return `<h3>목재</h3><div class="life-shop-grid"><article>${imageTag('life-lumber','목재')}<div><b>집과 수레에 쓸 목재</b><p>개당 8엽전 · 보유 ${s().inventory.lumber||0}개</p><div class="life-bundle-buttons">${[1,5,10].map(n=>`<button data-store-lumber="${n}" ${s().coins<n*8||(s().inventory.lumber||0)+n>99999?'disabled':''}>${n}개 · ${n*8}엽전</button>`).join('')}</div></div></article></div><p class="note">마을 남서쪽 길 건너 외곽 숲에서도 목재를 주울 수 있어. 각 지점은 3분 뒤 다시 생겨.</p><div class="life-workshop"><h3>집 확장 · 현재 ${h().level}단계</h3>${next?`<p>다음 ${h().level+1}단계: ${next.coins}엽전 · 목재 ${next.lumber}개<br>평판 ${h().reputation}/${g.reputation} · 부탁 ${h().commerce.completed}/${g.requests}회${g.harvest?' · 첫 수확 필요':''}</p><button id="store-upgrade" class="primary full" ${!canGrow(s())||s().coins<next.coins||(s().inventory.lumber||0)<next.lumber?'disabled':''}>집 확장 의뢰</button>`:'<p>가장 넉넉한 4단계 거처야.</p>'}<p>논 ${h().paddies}/${HOME_LEVELS[h().level].paddies}칸 · 다음 논 ${h().paddies?45:30}엽전</p><button id="store-paddy" ${h().paddies>=HOME_LEVELS[h().level].paddies||s().coins<(h().paddies?45:30)?'disabled':''}>논 한 칸 열기</button><button id="store-cart" class="full">선택 · 수레 제작</button></div>`;}
 function decor(){return `<h3>집 안과 마당의 살림 · 18종</h3><p>집의 꾸미기 메뉴에서 실제 크기를 보고 놓을 수 있어.</p><div class="life-shop-grid decor-store">${Object.entries(DECOR).map(([id,d])=>`<article>${imageTag(d.art,d.name)}<div><b>${d.name}</b><p>${d.area==='both'?'집 안·마당':d.area==='room'?'집 안':'마당'} · 보유 ${h().decorations[id]}개</p><p class="decor-use-tag">${decorDescription(id)}</p><small>${d.price}엽전${d.reputation?' · 평판 '+d.reputation+' 필요':''}</small></div><button data-store-decor="${id}" ${s().coins<d.price||h().reputation<(d.reputation||0)||h().decorations[id]>=99999?'disabled':''}>구매</button></article>`).join('')}</div>`;}
 function gather(e){const ready=woodReady(s(),e.id),left=Math.ceil(((s().resources[e.id]?.nextAt||0)-Date.now())/1000);panel('숲 가장자리의 목재',`${imageTag(ready?'shop-wood-pile':'shop-wood-empty','떨어진 목재')}<p>${ready?'떨어진 작은 목재를 주울 수 있어.':'이미 주웠다. 약 '+Math.max(1,Math.ceil(left/60))+'분 뒤 다시 살펴보자.'}</p><button id="life-gather-wood" class="primary full" ${ready?'':'disabled'}>목재 1개 줍기</button><p class="note">지점마다 3분 뒤 다시 생겨. 목공소에서도 살 수 있어.</p>`);$('#life-gather-wood').onclick=()=>{if(collectWood(s(),e.id)){done('목재 1개를 주웠다.');api.close();}else toast('위치와 가방을 다시 확인해 줘.');};}
 function interact(e){if(e.type==='lifeMerchant'){show(e.shopKind);return true;}if(e.type==='lifeWood'){gather(e);return true;}if(e.type==='lifeShopSign'){panel('마을 상점가',`<p>생활마을 북쪽 길로 나가면 별도 상점 거리에 네 전문 상점과 거래 상인이 있어.</p>${Object.entries(LIFE_SHOPS).map(([k,d])=>`<button data-store-guide="${k}" class="full">${d.name} 방향 보기</button>`).join('')}`);document.querySelectorAll('[data-store-guide]').forEach(b=>b.onclick=()=>guide(b.dataset.storeGuide));return true;}return false;}
 function adminPanel(){if(!api.admin())return;panel('생활 공간 · 상점 거리 · 외곽 숲 시험',`<p class="note">학생 원본과 분리된 관리자 시험 상태야. 상인 가까이로 이동한 뒤 실제 버튼으로 검사해.</p><div class="admin-section"><h3>세 나라 상점가</h3>${[['goguryeo','고구려'],['baekje','백제'],['silla','신라']].map(([c,n])=>`<button data-shop-qa-country="${c}">${n} 상점가</button>`).join('')}</div><div class="admin-section"><h3>생활 공간 · 실제 접근/거부 시험</h3>${[['village','생활마을'],['market','상점 거리'],['forest','외곽 숲'],['board','게시판 앞 · 부탁'],['trader','거래 상인 · 판매'],['room','집 안 · 생활 책상 없음'],['yard','마당 · 농사 관리판'],['workbench','마당 작업대'],['away','거래/부탁 거부 위치']].map(([k,n])=>`<button data-space-qa="${k}">${n}</button>`).join('')}</div><div class="admin-section"><h3>가게 방문</h3>${Object.entries(LIFE_SHOPS).map(([k,d])=>`<button data-shop-qa-visit="${k}">${d.name}</button>`).join('')}</div><div class="admin-section"><h3>구매 조건·기존 기능</h3>${[['ready','엽전·재료·평판 준비'],['poor','엽전·재료 부족'],['rep','평판 부족'],['owned','이미 보유한 도구'],['growth','거처 확장 직전'],['cart','수레 제작 직전'],['decor','18종 가구·배치 확인'],['wood','목재 채집 가능'],['wait','목재 재생 대기'],['reset','목재 재생시간 초기화']].map(([k,n])=>`<button data-shop-qa-case="${k}">${n}</button>`).join('')}</div><button id="shop-qa-back" class="full">관리자 메뉴</button>`,{wide:true});
  document.querySelectorAll('[data-space-qa]').forEach(b=>b.onclick=()=>{if(!h().owned)api.prepareAncient('4c');const country=s().ancient.country,k=b.dataset.spaceQa;const target={village:['ancient-village-'+country,{x:11,y:9}],market:[marketMap(country),{x:14,y:10}],forest:[forestMap(country),{x:19.7,y:9}],board:['ancient-village-'+country,{x:BOARD.x,y:BOARD.y+1}],trader:[marketMap(country),{x:TRADER.x,y:TRADER.y+1}],room:['ancient-home-'+country],yard:['ancient-yard-'+country,{x:12,y:9.5}],workbench:['ancient-yard-'+country,{x:17,y:9}],away:[marketMap(country),{x:14,y:16}]}[k];if(k==='workbench'&&h().level<2)setLifeLevel(h(),2);api.adminJump(...target);});
  document.querySelectorAll('[data-shop-qa-country]').forEach(b=>b.onclick=()=>{api.prepareAncient('4c');s().ancient.country=b.dataset.shopQaCountry;api.adminJump(marketMap(s().ancient.country),{x:14,y:10});});
  document.querySelectorAll('[data-shop-qa-visit]').forEach(b=>b.onclick=()=>{if(!h().owned)api.prepareAncient('4c');api.adminJump(shopMap(s().ancient.country,b.dataset.shopQaVisit),{x:5,y:3.6});});
  document.querySelectorAll('[data-shop-qa-case]').forEach(b=>b.onclick=()=>{if(!h().owned)api.prepareAncient('4c');const k=b.dataset.shopQaCase;
    if(['ready','growth','cart'].includes(k)){s().coins=3000;s().inventory.lumber=30;s().inventory.hide=10;h().reputation=45;h().commerce.completed=10;h().harvested.millet=4;}
    if(k==='poor'){s().coins=0;s().inventory.lumber=0;s().inventory.hide=0;}
    if(k==='rep'){h().reputation=0;h().harvested.millet=0;h().commerce.tools={seedBag:false,sickle:false,hearth:false};}
    if(k==='owned')h().commerce.tools={seedBag:true,sickle:true,hearth:true};
    if(k==='growth')setLifeLevel(h(),1);
    if(k==='cart'){setLifeLevel(h(),3);h().commerce.cart.owned=false;h().commerce.cart.commissioned=false;h().commerce.cart.active=null;}
    if(k==='decor'){for(const id of Object.keys(DECOR))h().decorations[id]=Math.max(1,h().decorations[id]);api.adminJump('ancient-home-'+s().ancient.country);return;}
    if(['wood','wait','reset'].includes(k)){for(const n of [1,2]){if(k==='wait')s().resources[woodId(s().ancient.country,n)]={nextAt:Date.now()+180000,slot:0};else delete s().resources[woodId(s().ancient.country,n)];}api.adminJump(forestMap(s().ancient.country),{x:8.8,y:7});return;}
    save();hud();adminPanel();
  });$('#shop-qa-back').onclick=api.adminPanel;
 }
 return {show,guide,interact,adminPanel};
}
